/// Like [`Parser::push_arg_values`] but for values that weren't actually present on the
/// command line (e.g. the implicit `true`/`false`/count used by [`ArgAction::SetTrue`],
/// [`ArgAction::SetFalse`], and [`ArgAction::Count`]).
///
/// These are synthesized by clap itself, so they shouldn't be run through the user's
/// [`ValueParser`][crate::builder::ValueParser] (e.g. an [`UnknownArgumentValueParser`]
/// would otherwise unconditionally reject the flag).
fn push_arg_values_synthetic<V: std::any::Any + Clone + Send + Sync + 'static>(
    &self,
    arg: &Arg,
    raw_vals: Vec<(OsString, V)>,
    matcher: &mut ArgMatcher,
) {
    for (raw_val, val) in raw_vals {
        // update the current index because each value is a distinct index to clap
        self.cur_idx.set(self.cur_idx.get() + 1);
        debug!(
            "Parser::add_single_val_to_arg: cur_idx:={}",
            self.cur_idx.get()
        );

        matcher.add_val_to(arg.get_id(), crate::util::AnyValue::new(val), raw_val);
        matcher.add_index_to(arg.get_id(), self.cur_idx.get());
    }
}

